import json
from typing import Any


class ResponseParser:
    """Parses JSON responses generated by the language model."""

    @staticmethod
    def parse(response: str) -> dict[str, Any]:
        """Extract and parse a JSON object from a model response.

        Args:
            response: Text generated by the language model.

        Returns:
            The parsed JSON object.

        Raises:
            ValueError: If the response does not contain valid JSON.
        """
        response = response.strip()

        if response.startswith("```"):
            lines = response.splitlines()
            response = "\n".join(lines[1:-1]).strip()

        try:
            result = json.loads(response)
        except json.JSONDecodeError as error:
            raise ValueError(
                f"Invalid JSON response: {error}"
            ) from error

        if not isinstance(result, dict):
            raise ValueError("Expected a JSON object.")

        return result
